// Helper to query Rapaport Price per Carat ($)
export const getRapPrice = (shapeCode, color, clarity, carat, customSheets = null) => {
  const sheets = customSheets || INITIAL_RAP_SHEETS;
  // Default fallback sheet (Round for fancy shapes if fancy shape matrix missing)
  const list = sheets[shapeCode] || sheets['PS'] || sheets['BR'] || [];
  
  const caratNum = parseFloat(carat) || 0;
  if (!caratNum) return 0;

  const match = list.find(r => 
    r.color.toUpperCase() === color.toUpperCase() && 
    r.clarity.toUpperCase() === clarity.toUpperCase() && 
    caratNum >= r.minCarat && caratNum <= r.maxCarat
  );

  if (match) return match.price;

  // Nearest carat bracket fallback estimation if exact bracket missing
  const colorMatches = list.filter(r => r.color.toUpperCase() === color.toUpperCase() && r.clarity.toUpperCase() === clarity.toUpperCase());
  if (colorMatches.length > 0) {
    colorMatches.sort((a, b) => Math.abs(a.minCarat - caratNum) - Math.abs(b.minCarat - caratNum));
    return colorMatches[0].price;
  }

  return 1200; // Baseline fallback
};
